export const OPENAPI_YAML: string = "openapi: 3.1.0\ninfo:\n  title: Talksasa Pay app API\n  version: \"2026-11-25\"\n  description: |\n    The API apps use to collect money through the Talksasa M-Pesa paybill,\n    like Paystack or Flutterwave. An app creates a **charge** (\"collect KES X\n    for my reference Y\"), the gateway prompts the customer's phone (STK push)\n    and/or the customer pays at the paybill with the charge's account number,\n    and the gateway reports the result, with the M-Pesa receipt, by webhook\n    and in the events feed. The gateway knows nothing about the app's\n    customers or invoices: keep your own mapping from `reference` (and\n    `metadata`) to your records.\n\n    **Authentication.** `Authorization: Bearer tsp_live_...` (or `tsp_test_`\n    outside production). Every request is scoped to the key's app; there is\n    no way to name another app (another app's ids are simply 404). A key may\n    be restricted to an IP allow-list (403 `ip_not_allowed` otherwise). A\n    suspended app's keys stop working (401).\n\n    **Money.** Amounts are integer Kenyan shillings (KES), 1 to 250,000 per\n    charge. There are no decimals. Apps can request and read money; they can\n    never record, move or refund it.\n\n    **Money rules.**\n      - A charge's amount, reference and account number never change. To\n        charge a different amount, cancel and create a new charge.\n      - `reference` is unique among all your charges (409\n        `duplicate_reference`).\n      - Every charge has an `account_number`: yours if you send one (it must\n        start with your account prefix, a hyphen and a digit, e.g.\n        `HOST-1042`), otherwise generated (`HOST-4K7QZ9M`). It is the\n        AccountReference of every prompt and what the customer types at the\n        paybill.\n      - A charge is `succeeded` only when Safaricom confirms a payment with\n        an M-Pesa receipt for exactly the charge amount. Each receipt counts\n        once.\n      - A failed prompt does NOT fail the charge: you get `stk_push.failed`\n        and the charge stays `pending` until it is paid, cancelled or\n        expires. Prompt again with `POST /charges/{id}/stk-push` (one live\n        prompt at a time).\n      - Late money is never dropped: money for an `expired` or `cancelled`\n        charge still makes it `succeeded` (`charge.succeeded`). Handle a\n        payment that arrives after you cancelled.\n      - Money for a charge that already succeeded (the customer paid twice)\n        is reported as `payment.received` with `duplicate_of_charge` set.\n        You (or Talksasa staff) refund it.\n      - Paybill payments whose account number starts with your prefix but\n        match no waiting charge (same account number and exact amount) are\n        reported as `payment.received`: you decide what they pay.\n      - Talksasa staff may record a reversal of a payment (e.g. Safaricom\n        reversed it): you get `transaction.reversed` and the charge becomes\n        `reversed`.\n\n    **Idempotency.** Every write is safe to retry. `POST /charges` and\n    `POST /charges/{id}/stk-push` require an `Idempotency-Key` header: the\n    same key with the same body returns the original result with 200 and\n    `Idempotent-Replayed: true`; the same key with a different body is 409\n    `idempotency_conflict`. Cancel is a no-op on an already-cancelled charge.\n\n    **Events.** Every change is delivered as a signed webhook AND is\n    available from `GET /events`, a gap-free feed. Webhooks are at least once\n    and may arrive out of order: de-duplicate by event `id`, and when in\n    doubt re-read the resource or the feed.\n\n    **Errors** are RFC 9457 `application/problem+json` with a stable `code`.\n    `429` and `503` carry `Retry-After`; back off and retry. `503 busy` and\n    `503 overloaded` mean nothing was changed. `503 timeout` means the\n    outcome is unknown: retry with the SAME Idempotency-Key (or re-read),\n    never with a new one. Quote `request_id` (also in the `X-Request-Id`\n    header) when asking for help.\nservers:\n  - url: /v1\nsecurity:\n  - apiKey: []\npaths:\n  /whoami:\n    get:\n      operationId: whoami\n      summary: The app this key belongs to\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/WhoAmI\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /charges:\n    post:\n      operationId: createCharge\n      summary: Create a charge (and optionally prompt the customer's phone)\n      description: |\n        Creates a `pending` charge for exactly `amount` KES. The response\n        carries `checkout_url` (a hosted pay page you can send the customer)\n        and `paybill` (manual M-Pesa instructions).\n\n        With `phone`, the first M-Pesa prompt is sent right away and\n        returned as `latest_stk_push`, exactly as `POST\n        /charges/{id}/stk-push` would. The charge is created even if the\n        prompt cannot be sent: `latest_stk_push` is then the `failed` push\n        (see its `result_desc`), or null when M-Pesa is unavailable. Prompt\n        again later or let the customer pay at the paybill.\n\n        Errors: 409 `duplicate_reference` (a charge with this reference\n        exists), 409 `idempotency_conflict`, 400 `idempotency_key_required`,\n        422 `validation_failed` (field errors in `errors`), 403\n        `app_suspended`.\n      parameters:\n        - $ref: \"#/components/parameters/IdempotencyKey\"\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: \"#/components/schemas/ChargeInput\" }\n      responses:\n        \"201\":\n          description: Created\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/Charge\" }\n        \"200\":\n          description: Replay of an earlier identical request (same Idempotency-Key)\n          headers:\n            Idempotent-Replayed: { schema: { type: string, enum: [\"true\"] } }\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/Charge\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n    get:\n      operationId: listCharges\n      summary: Charges, newest first\n      parameters:\n        - { name: status, in: query, schema: { $ref: \"#/components/schemas/ChargeStatus\" } }\n        - { name: reference, in: query, description: Exact reference, schema: { type: string, maxLength: 128 } }\n        - $ref: \"#/components/parameters/Cursor\"\n        - $ref: \"#/components/parameters/Limit\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [data, next_cursor]\n                properties:\n                  data: { type: array, items: { $ref: \"#/components/schemas/Charge\" } }\n                  next_cursor: { type: [string, \"null\"] }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /charges/{id}:\n    parameters:\n      - $ref: \"#/components/parameters/ID\"\n    get:\n      operationId: getCharge\n      summary: One charge, with its latest prompt\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/Charge\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /charges/{id}/stk-push:\n    parameters:\n      - $ref: \"#/components/parameters/ID\"\n    post:\n      operationId: sendSTKPush\n      summary: Send an M-Pesa payment prompt for the charge\n      description: |\n        Asks Safaricom to show \"Pay KES <amount> to Talksasa\" on the\n        customer's phone. The amount is always the charge's exact amount.\n        Only `pending` charges can be prompted (409 `not_payable`), and only\n        one prompt per charge can be live at a time (409 `stk_in_progress`\n        with the live push's id in `detail`). After a prompt fails, prompt\n        again.\n\n        The response is 202 with the push. Its outcome arrives as events:\n        `stk_push.sent`, then `stk_push.succeeded` together with\n        `charge.succeeded`, or `stk_push.failed` (`result_code` /\n        `result_desc`: cancelled by the customer, timed out, insufficient\n        funds, wrong PIN...; the charge stays pending). If Safaricom never\n        calls back, Talksasa checks with Safaricom after about a minute; a\n        success without a receipt becomes `stk_push.needs_review` and\n        `charge.needs_review` while staff confirm it — do NOT treat that as\n        paid.\n\n        Requires an `Idempotency-Key`: the same key returns the same push\n        (200, `Idempotent-Replayed: true`); the same key with a different\n        phone or charge is 409 `idempotency_conflict`. On `503 timeout`\n        retry with the SAME key: a new key could send the customer a second\n        prompt.\n\n        503 `mpesa_unavailable`: M-Pesa is not enabled in this environment.\n        502 `mpesa_error`: Safaricom refused or failed to send the prompt\n        (the failed push's id is in the problem's `detail`; nothing was\n        charged).\n      parameters:\n        - $ref: \"#/components/parameters/IdempotencyKey\"\n      requestBody:\n        required: true\n        content:\n          application/json:\n            schema: { $ref: \"#/components/schemas/STKPushInput\" }\n      responses:\n        \"202\":\n          description: Prompt sent (or being sent) to the phone\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/STKPush\" }\n        \"200\":\n          description: Replay of an earlier identical request (same Idempotency-Key)\n          headers:\n            Idempotent-Replayed: { schema: { type: string, enum: [\"true\"] } }\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/STKPush\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /charges/{id}/cancel:\n    parameters:\n      - $ref: \"#/components/parameters/ID\"\n    post:\n      operationId: cancelCharge\n      summary: Cancel a pending charge\n      description: |\n        Emits `charge.cancelled`. Idempotent: cancelling an already-cancelled\n        charge returns it with 200. Only `pending` charges can be cancelled\n        (409 `not_cancellable`). A live prompt is not withdrawn: if the\n        customer still pays, the charge becomes `succeeded`\n        (`charge.succeeded`) — late money is never dropped.\n      responses:\n        \"200\":\n          description: Cancelled\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/Charge\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /stk-pushes/{id}:\n    parameters:\n      - $ref: \"#/components/parameters/ID\"\n    get:\n      operationId: getSTKPush\n      summary: One STK push\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/STKPush\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /transactions:\n    get:\n      operationId: listTransactions\n      summary: Money received (and reversed) for your app, newest first\n      parameters:\n        - { name: charge_id, in: query, schema: { type: string, format: uuid } }\n        - { name: since, in: query, schema: { type: string, format: date-time } }\n        - $ref: \"#/components/parameters/Cursor\"\n        - $ref: \"#/components/parameters/Limit\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [data, next_cursor]\n                properties:\n                  data: { type: array, items: { $ref: \"#/components/schemas/Transaction\" } }\n                  next_cursor: { type: [string, \"null\"] }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /transactions/{id}:\n    parameters:\n      - $ref: \"#/components/parameters/ID\"\n    get:\n      operationId: getTransaction\n      summary: One transaction\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema: { $ref: \"#/components/schemas/Transaction\" }\n        default: { $ref: \"#/components/responses/Problem\" }\n\n  /events:\n    get:\n      operationId: listEvents\n      summary: Gap-free feed of every event, oldest first\n      description: |\n        Store `next_cursor` after processing a page and pass it as `after`\n        next time. The feed never skips an event, even one whose transaction\n        committed late, so polling it is a complete alternative (or backstop)\n        to webhooks. Start with no `after` to read from the beginning.\n      parameters:\n        - { name: after, in: query, schema: { type: string, maxLength: 200 } }\n        - $ref: \"#/components/parameters/Limit\"\n      responses:\n        \"200\":\n          description: OK\n          content:\n            application/json:\n              schema:\n                type: object\n                required: [data, next_cursor, has_more]\n                properties:\n                  data: { type: array, items: { $ref: \"#/components/schemas/Event\" } }\n                  next_cursor: { type: [string, \"null\"], description: \"Pass as `after`; null when data is empty (keep your previous cursor).\" }\n                  has_more: { type: boolean }\n        default: { $ref: \"#/components/responses/Problem\" }\n\nwebhooks:\n  event:\n    post:\n      summary: An event, delivered to the app's webhook URL\n      description: |\n        Headers:\n          - `Talksasa-Event-Id`: the event id (de-duplicate on it)\n          - `Talksasa-Event-Type`\n          - `Talksasa-Signature: t=<unix seconds>,v1=<hex>[,v1=<hex>]` where\n            `v1 = HMAC-SHA256(webhook_secret, \"<t>.<raw body>\")`. Accept if\n            ANY v1 matches (two appear for 24 h after a secret rotation) and\n            `|now - t| <= 300` seconds. Compare in constant time.\n        Respond 2xx within 10 s. Anything else (or a timeout) is retried\n        with backoff for about 3 days. Process asynchronously if slow.\n      requestBody:\n        content:\n          application/json:\n            schema: { $ref: \"#/components/schemas/Event\" }\n      responses:\n        \"200\": { description: Accepted }\n\ncomponents:\n  securitySchemes:\n    apiKey:\n      type: http\n      scheme: bearer\n      description: \"App API key: tsp_live_<key id>_<secret> (tsp_test_ outside production).\"\n  parameters:\n    ID:\n      name: id\n      in: path\n      required: true\n      schema: { type: string, format: uuid }\n    IdempotencyKey:\n      name: Idempotency-Key\n      in: header\n      required: true\n      description: Unique per logical request (e.g. a UUID, or \"invoice-123-v1\"). Kept forever.\n      schema: { type: string, minLength: 1, maxLength: 255 }\n    Cursor:\n      name: cursor\n      in: query\n      schema: { type: string, maxLength: 200 }\n    Limit:\n      name: limit\n      in: query\n      schema: { type: integer, minimum: 1, maximum: 200, default: 50 }\n  responses:\n    Problem:\n      description: Error\n      headers:\n        Retry-After: { schema: { type: integer }, description: \"Seconds; on 429 and 503\" }\n      content:\n        application/problem+json:\n          schema: { $ref: \"#/components/schemas/Problem\" }\n  schemas:\n    Problem:\n      type: object\n      required: [type, title, status]\n      properties:\n        type: { type: string }\n        title: { type: string }\n        status: { type: integer }\n        detail: { type: string }\n        code:\n          type: string\n          description: Stable machine-readable code.\n          enum:\n            - unauthorized\n            - ip_not_allowed\n            - app_suspended\n            - rate_limited\n            - overloaded\n            - busy\n            - timeout\n            - not_found\n            - method_not_allowed\n            - validation_failed\n            - invalid_json\n            - unsupported_media_type\n            - payload_too_large\n            - idempotency_key_required\n            - idempotency_conflict\n            - duplicate_reference\n            - not_cancellable\n            - not_payable\n            - amount_too_large\n            - stk_in_progress\n            - mpesa_unavailable\n            - mpesa_error\n            - not_implemented\n            - internal_error\n        request_id: { type: string }\n        errors:\n          type: array\n          items:\n            type: object\n            required: [field, message]\n            properties:\n              field: { type: string }\n              message: { type: string }\n    WhoAmI:\n      type: object\n      required: [app_id, app_name, account_prefix, key_id]\n      properties:\n        app_id: { type: string, format: uuid }\n        app_name: { type: string }\n        account_prefix: { type: string, description: \"Your paybill account-number prefix, e.g. HOST\" }\n        key_id: { type: string }\n    ChargeInput:\n      type: object\n      additionalProperties: false\n      required: [reference, amount]\n      properties:\n        reference:\n          type: string\n          minLength: 1\n          maxLength: 128\n          description: Your own reference (invoice number, order id). Unique among your charges.\n        amount: { type: integer, minimum: 1, maximum: 250000, description: KES }\n        description: { type: string, minLength: 1, maxLength: 500, description: Shown to the customer on the pay page }\n        phone:\n          type: string\n          maxLength: 20\n          description: \"Optional Safaricom number to prompt right away: 07XXXXXXXX, 01XXXXXXXX, 2547XXXXXXXX or +2547XXXXXXXX\"\n        account_number:\n          type: string\n          maxLength: 12\n          pattern: \"^[A-Z]{2,6}-[0-9][A-Z0-9]*$\"\n          description: |\n            Optional. Your own account number for this charge (e.g. your\n            customer number HOST-1042): your prefix, a hyphen, a digit, then\n            A-Z/0-9, at most 12 characters. Omit it to get a generated one.\n        metadata:\n          type: object\n          additionalProperties: true\n          description: Any JSON object up to 4096 bytes, echoed back on the charge and its events.\n        expires_in:\n          type: integer\n          minimum: 900\n          maximum: 604800\n          default: 86400\n          description: Seconds until a pending charge expires (15 minutes to 7 days; default 24 hours).\n    ChargeStatus:\n      type: string\n      enum: [pending, needs_review, succeeded, expired, cancelled, reversed]\n      description: |\n        pending: waiting for money (prompts may be retried). needs_review:\n        Safaricom said paid without a receipt; staff are checking (not paid\n        yet). succeeded: paid; see transaction_id. expired / cancelled: no\n        longer prompted (late money still succeeds it). reversed: staff\n        reversed the payment.\n    Paybill:\n      type: object\n      required: [business_number, account_number]\n      properties:\n        business_number: { type: string, description: The Talksasa paybill number }\n        account_number: { type: string, description: What the customer types as the account number }\n    Charge:\n      type: object\n      required: [object, id, reference, amount, currency, description, metadata, account_number, status, checkout_url, paybill,\n        expires_at, succeeded_at, transaction_id, latest_stk_push, created_at, updated_at]\n      properties:\n        object: { type: string, const: charge }\n        id: { type: string, format: uuid }\n        reference: { type: string }\n        amount: { type: integer, description: KES }\n        currency: { type: string, enum: [KES] }\n        description: { type: [string, \"null\"] }\n        metadata: { type: [object, \"null\"], additionalProperties: true, description: As you sent it }\n        account_number: { type: string, description: \"Paybill account number and STK AccountReference, e.g. HOST-1042\" }\n        status: { $ref: \"#/components/schemas/ChargeStatus\" }\n        checkout_url: { type: string, format: uri, description: Hosted pay page for this charge }\n        paybill:\n          description: Manual M-Pesa instructions while the charge can be paid (pending or needs_review); null otherwise\n          oneOf:\n            - $ref: \"#/components/schemas/Paybill\"\n            - { type: \"null\" }\n        expires_at: { type: string, format: date-time }\n        succeeded_at: { type: [string, \"null\"], format: date-time }\n        transaction_id: { type: [string, \"null\"], format: uuid, description: The payment that made the charge succeed }\n        latest_stk_push:\n          description: The charge's newest prompt, if any\n          oneOf:\n            - $ref: \"#/components/schemas/STKPush\"\n            - { type: \"null\" }\n        created_at: { type: string, format: date-time }\n        updated_at: { type: string, format: date-time }\n    Transaction:\n      type: object\n      required: [object, id, kind, direction, channel, status, amount, currency, receipt, phone, account_number, charge_id,\n        reverses_transaction_id, occurred_at, created_at, completed_at]\n      properties:\n        object: { type: string, const: transaction }\n        id: { type: string, format: uuid }\n        kind: { type: string, enum: [payment, refund, reversal, adjustment] }\n        direction: { type: string, enum: [in, out] }\n        channel: { type: string, enum: [mpesa_stk, mpesa_c2b, mpesa_b2c, manual] }\n        status: { type: string, enum: [pending, succeeded, failed, cancelled, needs_review] }\n        amount: { type: integer }\n        currency: { type: string, enum: [KES] }\n        receipt: { type: [string, \"null\"], description: M-Pesa receipt number }\n        phone: { type: [string, \"null\"], description: Masked }\n        account_number: { type: [string, \"null\"], description: The account number as the customer typed it (paybill) or as sent with the prompt }\n        charge_id: { type: [string, \"null\"], format: uuid, description: The charge this money was for, when known }\n        reverses_transaction_id: { type: [string, \"null\"], format: uuid }\n        occurred_at: { type: [string, \"null\"], format: date-time }\n        created_at: { type: string, format: date-time }\n        completed_at: { type: [string, \"null\"], format: date-time }\n    PaymentReceived:\n      description: |\n        Data of `payment.received`: a payment routed to your app that did not\n        pay a waiting charge. `duplicate_of_charge` is set when it named a\n        charge that had already succeeded (the customer paid twice).\n      allOf:\n        - $ref: \"#/components/schemas/Transaction\"\n        - type: object\n          required: [duplicate_of_charge]\n          properties:\n            duplicate_of_charge: { type: [string, \"null\"], format: uuid }\n    STKPushInput:\n      type: object\n      additionalProperties: false\n      required: [phone]\n      properties:\n        phone:\n          type: string\n          description: \"Safaricom number to prompt: 07XXXXXXXX, 01XXXXXXXX, 2547XXXXXXXX or +2547XXXXXXXX\"\n          maxLength: 20\n    STKPush:\n      type: object\n      required: [object, id, charge_id, transaction_id, status, amount, phone, checkout_request_id, result_code, result_desc,\n        created_at, updated_at, completed_at]\n      properties:\n        object: { type: string, const: stk_push }\n        id: { type: string, format: uuid }\n        charge_id: { type: string, format: uuid }\n        transaction_id: { type: string, format: uuid, description: \"The M-Pesa transaction that holds (or will hold) this payment: pending until Safaricom answers. If the payment arrived after the prompt had been given up, it is the new transaction it was recorded on.\" }\n        status:\n          type: string\n          enum: [initiating, sent, succeeded, failed, needs_review]\n          description: |\n            initiating: being sent to Safaricom. sent: on the customer's phone.\n            succeeded: paid (receipt recorded). failed: see result_code/result_desc\n            (the charge stays pending). needs_review: Safaricom reported success\n            without a receipt; staff are confirming. Not paid until\n            charge.succeeded arrives.\n        amount: { type: integer }\n        phone: { type: string, description: Masked }\n        checkout_request_id: { type: [string, \"null\"], description: \"Safaricom's CheckoutRequestID (quote it to support)\" }\n        result_code: { type: [string, \"null\"], description: \"Safaricom result code, e.g. 1032 = cancelled by the customer, 1037 = phone unreachable, 1 = insufficient funds, 2001 = wrong PIN\" }\n        result_desc: { type: [string, \"null\"] }\n        created_at: { type: string, format: date-time }\n        updated_at: { type: string, format: date-time }\n        completed_at: { type: [string, \"null\"], format: date-time }\n    EventType:\n      type: string\n      enum:\n        - charge.succeeded\n        - charge.needs_review\n        - charge.expired\n        - charge.cancelled\n        - stk_push.sent\n        - stk_push.failed\n        - stk_push.succeeded\n        - stk_push.needs_review\n        - payment.received\n        - transaction.reversed\n    Event:\n      type: object\n      required: [object, id, type, api_version, created_at, data]\n      properties:\n        object: { type: string, const: event }\n        id: { type: string, format: uuid }\n        type: { $ref: \"#/components/schemas/EventType\" }\n        api_version: { type: string }\n        created_at: { type: string, format: date-time }\n        data:\n          description: |\n            State at the time of the event: charge.* -> Charge;\n            stk_push.* -> STKPush; payment.received -> PaymentReceived;\n            transaction.reversed -> Transaction (the reversal transaction;\n            its reverses_transaction_id names the payment, its charge_id the\n            charge that is now reversed).\n          oneOf:\n            - $ref: \"#/components/schemas/Charge\"\n            - $ref: \"#/components/schemas/STKPush\"\n            - $ref: \"#/components/schemas/PaymentReceived\"\n            - $ref: \"#/components/schemas/Transaction\"\n";
